function renderizar() {
  // 1. Limpa o container visual anterior
  container.innerHTML = "";

  // 2. Reconstrói os nós a partir do estado atual
  const fragmento = document.createDocumentFragment();
  estado.forEach(item => {
    const li = document.createElement("li");
    li.className = "item";
    li.textContent = item.texto;
    fragmento.append(li);
  });
  container.append(fragmento);
}

